-- 원본 47798행 / 제외 10255행 / 마스터 14283행 / 동의어 37543행
-- =====================================================================

USE commondb;

SET NAMES utf8mb4;
SET autocommit = 0;
SET unique_checks = 0;
SET foreign_key_checks = 0;

-- 동의어는 전량 교체한다. 참조하는 테이블이 없으므로 TRUNCATE 가 안전하다.
TRUNCATE TABLE icd_code_synonym;

-- ---------------------------------------------------------------------
-- 1. icd_code - 마스터 14283행 (UPSERT)
--
--    DELETE 하지 않는다. chart.icd_code 가 ON DELETE RESTRICT 로 참조하므로
--    진료 기록이 하나라도 있으면 DELETE 는 FK 위반으로 실패한다.
--    KCD 개정본 재적재는 UPSERT 로 처리한다.
-- ---------------------------------------------------------------------
AS new ON DUPLICATE KEY UPDATE
  name_kr=new.name_kr, name_en=new.name_en,
  gender_restriction=new.gender_restriction,
